&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Kleine Teams mit spannenden Projekten in der Automobilbranche mit viel Raum für selbstständiges Arbeiten und Weiterentwicklung&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:1,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:709,&amp;quot;335559738&amp;quot;:42,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:237}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
