&lt;li&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:1,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:709,&amp;quot;335559738&amp;quot;:42,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:237}&quot;&gt;Wellbeing-Packages (EGYM Wellpass, OpenUp)&lt;/span&gt;&lt;/li&gt;
